parameters.jsCode:
return [{
  json: {
    candidateName: 'Arjun Sharma',
    roleTitle: 'Senior Cloud Architect',
    department: 'Platform Engineering',
    workLocation: 'Bangalore, India',
    joiningDate: '2026-11-01',
    annualCtc: 1800000,
    basicPercentage: 50,
    hiringManager: 'Pooja Iyer'
  }
}];

const candidate = $('Sample Candidate Selection Ingest').first().json;
const slugData = $('DevDeskApp: Candidate Slugifier').first().json;
const payroll = $('DevDeskApp: Indian CTC Payroll Engine').first().json;
const uuidData = $('DevDeskApp: Offer Tracking UUID').first().json;
const hashData = $('DevDeskApp: Compensation Hasher').first().json;

const offerCode = `OFFER-${slugData.slug.substring(0, 18).toUpperCase()}-${uuidData.uuid.substring(0, 8).toUpperCase()}`;

return [{
  json: {
    status: 'OFFER_READY_FOR_DISPATCH',
    offerReferenceId: offerCode,
    candidate: {
      name: candidate.candidateName,
      role: candidate.roleTitle,
      department: candidate.department,
      location: candidate.workLocation,
      joiningDate: candidate.joiningDate
    },
    payrollBreakdown: {
      annualCtcFormatted: `₹${candidate.annualCtc.toLocaleString('en-IN')}`,
      monthlyGrossFormatted: `₹${(payroll.monthlyGross || 0).toLocaleString('en-IN')}`,
      estimatedMonthlyInHandFormatted: `₹${(payroll.monthlyInHand || 0).toLocaleString('en-IN')}`,
      deductions: {
        monthlyBasicFormatted: `₹${(payroll.breakdown?.monthlyBasic || 0).toLocaleString('en-IN')}`,
        employeePfFormatted: `₹${(payroll.breakdown?.employeePf || 0).toLocaleString('en-IN')}`,
        professionalTaxFormatted: `₹${payroll.breakdown?.professionalTax || 200}`,
        estimatedTdsFormatted: `₹${(payroll.breakdown?.estimatedMonthlyTds || 0).toLocaleString('en-IN')}`
      }
    },
    securityProof: {
      algorithm: 'sha256',
      checksum: hashData.hash
    },
    timestamp: new Date().toISOString()
  }
}];
